	for (int i = 0; i < particleCubeWidth; i++) {
		for (int j = 0; j < particleCubeWidth; j++) {
			for (int k = 0; k < particleCubeWidth; k++) {
				float ranX
                    = (float(rand()) / float((RAND_MAX)) * 0.5f - 1)
